# Source for q/ae-mix-final.js: Echo instrumentation + Contrast (fourth) + Anatomy + Physiology (fifth).
EI="Echo instrumentation"; CT="Contrast"; AN="Anatomy"; PH="Physiology"
Q=[
# --- Echo instrumentation ---
(EI,"Infants are usually scanned with transducer frequencies of about:","5 to 12 MHz",["1 to 2 MHz","20 to 30 MHz","0.5 MHz"],"Small hearts close to the skin allow high frequencies.","F"),
(EI,"Adult TEE probes usually operate at about:","3 to 7 MHz",["1 MHz only","15 to 20 MHz","0.5 MHz"],"The esophagus is close to the heart, so higher frequencies can be used.","F"),
(EI,"The TEE probe handle controls allow:","Anteflexion, retroflexion, side-to-side flexion and rotation of the imaging plane from 0° to 180°",["Only depth changes","Only Doppler","Only zoom"],"Multiplane rotation gives many views from one probe position.","F"),
(EI,"Modern 3D TEE probes contain:","A matrix array in the tip",["A single crystal","No crystals","A mechanical motor only"],"They allow live 3D, biplane and multiplane imaging.","F"),
(EI,"Intracardiac echo (ICE) catheters typically use:","A small phased array at the catheter tip",["A large external probe","A TEE probe","A linear probe on the chest"],"They are usually inserted through a femoral vein.","F"),
(EI,"Handheld (pocket) ultrasound devices are best used for:","Quick focused bedside questions, not full diagnostic studies",["Replacing all full echo exams","Strain measurements","3D TEE"],"Findings may need a full echo to confirm.","F"),
(EI,"Speckle-tracking strain works by:","Following natural speckle patterns from frame to frame",["Measuring Doppler shift only","Measuring blood velocity","Using contrast bubbles"],"It is less angle dependent than tissue Doppler.","F"),
(EI,"Strain rate measures:","How fast deformation (strain) happens over time",["Total deformation","Blood velocity","Valve area"],"Its unit is per second (s⁻¹).","C"),
(EI,"Color tissue Doppler differs from pulsed tissue Doppler because it:","Shows mean velocities over a whole region, which can be analyzed offline",["Shows peak velocities only","Uses CW","Measures blood flow"],"Pulsed TDI values are usually about 20% higher than color TDI values.","C"),
(EI,"In 3D echo, setting the 3D gain too low can cause:","Dropout artifacts that look like holes, such as a false ASD",["Blurry thick structures","Higher volume rates","Better resolution"],"Too much gain makes structures look thick and blurry.","C"),
(EI,"3D rendering modes include:","Volume rendering, surface rendering and multiplanar views",["A-mode only","M-mode only","Spectral Doppler only"],"Each mode shows the data in a different way.","F"),
(EI,"3D color Doppler typically has:","A low volume rate, so a narrow volume is used",["A very high volume rate","No limitations","Better spatial detail than 2D"],"Multi-beat acquisition can raise the rate.","F"),
(EI,"Machine presets (adult cardiac, pediatric, contrast) are used to:","Start with settings suited to the exam type",["Lock all settings","Replace optimization","Increase exposure"],"Adjust settings further for each patient.","F"),
(EI,"A DICOM structured report (SR) is used to:","Send measurements from the machine to the reporting system automatically",["Store only images","Print images","Clean the machine"],"It reduces typing errors.","C"),
(EI,"A DICOM modality worklist allows the machine to:","Receive patient details from the scheduling system",["Clean probes","Measure EF","Change frequency"],"It prevents errors from typing names by hand.","F"),
(EI,"Ultrasound machine air filters should be:","Cleaned regularly to prevent overheating",["Never touched","Removed permanently","Covered with tape"],"Follow the manufacturer's maintenance schedule.","F"),
(EI,"To protect transducer cables, the sonographer should:","Avoid kinking, running over or tightly wrapping them",["Coil them tightly","Leave them on the floor","Hang the probe by its cable"],"Damaged cables can affect images and safety.","F"),
(EI,"Transducer surface temperature can rise mainly with:","High output and long dwell times, especially in Doppler",["Low output B-mode only","Freezing the image","Turning off the machine"],"Freeze the image when not actively scanning.","F"),
(EI,"Contrast-specific imaging modes such as pulse inversion and power (amplitude) modulation work by:","Cancelling linear tissue echoes and keeping nonlinear bubble echoes",["Increasing tissue echoes","Using CW","Raising MI to maximum"],"This makes contrast-filled areas bright and tissue dark.","C"),
(EI,"3D image quality depends strongly on:","The quality of the 2D window and image",["Only the software","The monitor","Patient age only"],"A poor 2D window gives a poor 3D dataset.","F"),
# --- Contrast ---
(CT,"Definity (perflutren lipid) must be prepared before use by:","Shaking (activating) the vial in a mechanical shaker",["Freezing it","Mixing with blood","Boiling it"],"Follow the product instructions for timing and storage.","C"),
(CT,"Lumason (sulfur hexafluoride microbubbles) is prepared by:","Reconstituting the powder with saline and shaking by hand",["Mechanical activation","Heating","Freezing"],"Each agent has its own preparation steps.","C"),
(CT,"Optison (albumin microspheres) is prepared by:","Gently inverting the vial to resuspend the bubbles",["Mechanical shaking for minutes","Mixing with water","Heating"],"Avoid vigorous shaking that can damage the bubbles.","C"),
(CT,"The gas from ultrasound enhancing agents is mostly removed from the body by:","Breathing it out through the lungs",["The kidneys","The liver as bile","Sweat"],"This is why UEAs do not harm the kidneys.","F"),
(CT,"At very low MI, microbubbles respond:","Mostly linearly; at slightly higher low MI they oscillate nonlinearly; at high MI they break",["By breaking immediately","By staying still","Only at CW"],"Contrast imaging uses the nonlinear range.","C"),
(CT,"Smaller microbubbles resonate at:","Higher frequencies",["Lower frequencies","The same frequency","No frequency"],"Bubbles of 1–10 µm resonate in the diagnostic frequency range.","C"),
(CT,"A dark, swirling apex with good contrast in the rest of the LV may be caused by:","Bubble destruction in the near field, where MI is highest",["Normal filling","A large thrombus always","Too low MI"],"Lower the MI or move the focus.","C"),
(CT,"A weak TR signal can be enhanced for a better PASP estimate by:","Agitated saline or a UEA",["Increasing wall filter","Lowering frequency only","Using M-mode"],"Do not overestimate velocity from blooming.","F"),
(CT,"When contrast is given during a stress echo, it is usually given:","At rest and again at peak stress",["Only after the test","Only at rest","Never"],"Each stage needs adequate opacification.","F"),
(CT,"Too little contrast in the LV often shows:","Swirling and incomplete opacification",["Far-field shadowing","Very bright uniform LV","Blooming in Doppler"],"Give more contrast or adjust the infusion rate.","F"),
(CT,"Patients receiving UEAs should be monitored:","During and for a short time after the injection for reactions",["Not at all","Only the next day","Only if they ask"],"Follow lab policy and the product label.","F"),
(CT,"UEAs can be used in patients with kidney failure because they:","Are not cleared by the kidneys",["Damage the kidneys","Contain iodine","Contain gadolinium"],"This differs from iodinated CT contrast.","F"),
(CT,"A contrast study that shows the LV cavity well but the myocardium remains dark in one territory at rest suggests:","A perfusion defect, such as scar or ischemia",["Normal perfusion","A pericardial effusion","Artifact always"],"Interpret with wall motion.","C"),
(CT,"Contrast helps in suspected LV noncompaction because it:","Fills the deep recesses between trabeculations, showing the two layers",["Hides trabeculations","Measures strain","Shows the aorta"],"The noncompacted layer becomes clear.","F"),
(CT,"Agitated saline injected during TEE can help show:","A PFO or ASD with right-to-left shunting",["Coronary flow","LV perfusion","Aortic valve area"],"Valsalva release during TEE can be harder with sedation.","F"),
# --- Anatomy ---
(AN,"Normal aortic valve area in adults is about:","3 to 4 cm²",["0.5 to 1 cm²","8 to 10 cm²","15 cm²"],"Severe AS is 1.0 cm² or less.","F"),
(AN,"Normal mitral valve area in adults is about:","4 to 6 cm²",["1 cm²","10 to 12 cm²","0.5 cm²"],"Severe MS is 1.5 cm² or less.","F"),
(AN,"Compared with the mitral valve, the normal tricuspid valve area is:","Larger (about 7 to 9 cm²)",["Smaller (about 1 cm²)","The same","Not measurable"],"The tricuspid is the largest heart valve.","C"),
(AN,"The interatrial groove (Waterston's groove) is a surgical landmark used to reach the:","Left atrium",["Right ventricle","Aortic arch","Coronary sinus"],"Surgeons open it to approach the mitral valve.","C"),
(AN,"The right pulmonary artery passes:","Behind the ascending aorta and below the aortic arch",["In front of the aorta","Above the arch","Behind the esophagus"],"It is seen in cross section beneath the arch in the suprasternal view.","F"),
(AN,"The left pulmonary artery passes:","Over the left main bronchus",["Under the right bronchus","Behind the esophagus","Through the diaphragm"],"It connects to the aortic arch via the ligamentum arteriosum.","C"),
(AN,"The main pulmonary trunk in adults is about how long before it divides?","About 5 cm",["About 1 cm","About 20 cm","About 50 cm"],"It divides into the right and left pulmonary arteries.","C"),
(AN,"In infants, a large structure in the anterior mediastinum seen from the suprasternal or high parasternal window may be the:","Thymus",["Thyroid","Liver","Spleen"],"It shrinks with age.","C"),
(AN,"The descending thoracic aorta lies:","Behind the left atrium, to the left of the spine",["In front of the RV","Inside the pericardium only","To the right of the spine"],"It is seen in cross section in PLAX.","F"),
(AN,"Normal LV end-diastolic wall thickness in adults is about:","About 6 to 10 mm (slightly higher upper limit in men)",["2 to 3 mm","15 to 20 mm","25 mm"],"Over 15 mm raises concern for HCM in adults.","F"),
(AN,"The anterior and posterior papillary muscles of the LV arise from the:","Lower and mid ventricular wall",["Mitral annulus","Aortic root","Atrial wall"],"They attach to both mitral leaflets via chordae.","F"),
(AN,"The trachea lies:","Behind the aortic arch and in front of the esophagus",["In front of the heart","Inside the pericardium","Behind the spine"],"A right-sided arch passes to the right of the trachea.","C"),
(AN,"The thoracic duct drains lymph into the:","Junction of the left subclavian and left internal jugular veins",["Right atrium directly","Coronary sinus","Pulmonary artery"],"Injury causes chylothorax or chylopericardium.","C"),
# --- Physiology ---
(PH,"Normal resting stroke volume in adults is about:","60 to 100 mL",["10 to 20 mL","200 to 300 mL","500 mL"],"Stroke volume index normally exceeds 35 mL/m².","F"),
(PH,"Normal resting cardiac output in adults is about:","4 to 8 L/min",["1 L/min","15 to 20 L/min","40 L/min"],"It can rise several times during exercise.","F"),
(PH,"Normal resting mean pulmonary artery pressure is about:","14 mmHg (under 20 mmHg)",["40 mmHg","60 mmHg","5 mmHg"],"PH is defined as mean PAP over 20 mmHg.","F"),
(PH,"Normal PA systolic pressure is about:","15 to 30 mmHg",["50 to 60 mmHg","100 to 120 mmHg","0 to 5 mmHg"],"PA pressures are much lower than aortic pressures.","F"),
(PH,"Normal LV end-diastolic pressure is under about:","12 mmHg",["30 mmHg","50 mmHg","100 mmHg"],"Raised LVEDP is a feature of diastolic dysfunction.","F"),
(PH,"At a heart rate of 75 bpm, one cardiac cycle lasts about:","0.8 seconds",["0.2 seconds","2 seconds","1.5 seconds"],"About 0.3 s is systole and 0.5 s is diastole.","F"),
(PH,"The slowest conduction in the heart's electrical system is in the:","AV node",["Purkinje fibers","Bundle of His","Atrial muscle"],"Purkinje fibers conduct fastest.","F"),
(PH,"If the SA node fails, the AV junction usually takes over at about:","40 to 60 bpm",["60 to 100 bpm","100 to 150 bpm","10 bpm"],"Ventricular escape rhythms are about 20 to 40 bpm.","F"),
(PH,"Each gram of hemoglobin, when fully saturated, carries about:","1.34 mL of oxygen",["10 mL","0.01 mL","100 mL"],"Oxygen content depends mostly on hemoglobin and saturation.","C"),
(PH,"Antidiuretic hormone (ADH) is released when:","Blood volume falls or blood becomes more concentrated",["Blood volume rises","Blood pressure is very high","The patient drinks too much water"],"It makes the kidneys save water.","F"),
(PH,"Adrenaline (epinephrine) acting on the heart:","Increases heart rate and contractility",["Lowers heart rate","Lowers contractility","Stops the heart"],"It is used in cardiac arrest and anaphylaxis.","F"),
(PH,"Venous return equals cardiac output:","Over time in a stable circulation",["Never","Only during exercise","Only in the fetus"],"What goes out must come back.","F"),
(PH,"The LV fills mostly during:","Early diastole (rapid filling)",["Atrial systole only","Isovolumic contraction","Systole"],"Atrial contraction adds a smaller final part.","F"),
(PH,"The pressure difference that drives blood through the systemic circulation is between the:","Aorta and right atrium",["LA and LV","PA and LA","RV and RA"],"Mean arterial pressure minus RA pressure.","F"),
(PH,"Cardiac muscle cells are connected by intercalated discs with gap junctions, which allow:","Electrical signals to pass quickly from cell to cell",["Blood to flow between cells","Valves to open","Lymph drainage"],"This lets the heart contract as a unit.","F"),
]
